fn find(a: Vec<i32>, key: i32) -> usize {
    // Iterate through the vector and return the index of the first matching element.
    // If no element matches, return the length of the vector.
    a.iter()
     .position(|&x| x == key)
     .unwrap_or(a.len())
}

